// the whole hero re-tints to the active event (kept within the brand purple→pink range)\n}\nfunction showSlide(i) {\n  const n = deckItems.length; if (!n) return;\n  bannerIdx = (i + n) % n; layoutDeck(); fillInfo();\n  document.querySelectorAll(\"#banner [data-dot]\").forEach((d, k) => d.classList.toggle(\"on\", k === bannerIdx));\n}\nfunction stopBanner() { clearInterval(bannerTimer); bannerTimer = null; }\nfunction startBanner() {\n  stopBanner();\n  if (deckItems.length < 2 || reduced) return;\n  bannerTimer = setInterval(() => showSlide(bannerIdx + 1), 5200);\n}\nfunction renderBanner() {\n  const box = $(\"banner\"); if (!box) return;\n  stopBanner(); bannerIdx = 0; deckItems = bannerItems();\n  if (!deckItems.length) {\n    box.innerHTML = '<div class=\"deck-ph\"><div><div class=\"dposter\" style=\"background:linear-gradient(135deg,#3a1458,#1a0f26)\">🔥</div><b>Trending events will appear here</b><br><small class=\"muted\">Check back soon — new events are added all the time.</small></div></div>';\n    setHue(285); return;\n  }\n  box.innerHTML = `<div class=\"deck-stage\" id=\"stage\">${deckItems.map((e, i) => `<div class=\"dcard\" data-i=\"${i}\" data-id=\"${safe(e.id)}\">${posterHtml(e)}<span class=\"dbadge\">${i === 0 ? \"🔥 #1 TRENDING\" : \"#\" + (i + 1)}</span><div class=\"dgloss\"></div><div class=\"dname\">${safe(trunc(e.title, 34))}<small>${safe(e.city)} · ${money(e.price)}</small></div></div>`).join(\"\")}</div><div class=\"deck-info\" id=\"deckInfo\"></div>` +\n    (deckItems.length > 1 ? `<div class=\"deck-ctrl\"><button class=\"bn-arrow\" data-dir=\"-1\" aria-label=\"Previous\">‹</button><div class=\"dots\">${deckItems.map((_, i) => `<i data-dot=\"${i}\"${i === 0 ? ' class=\"on\"' : \"\"}></i>`).join(\"\")}</div><button class=\"bn-arrow\" data-dir=\"1\" aria-label=\"Next\">›</button></div>` : \"\");\n  layoutDeck(true); fillInfo(); startBanner();\n}\n\n/* ---------- home page extras: ticker, vibe tiles, stats, motion ---------- */\nconst VIBES = [[\"Nightclubs\", \"🪩\", 285, \"Clubs\"], [\"Lounges\", \"🍸\", 330, \"Lounges\"], [\"Concerts\", \"🎤\", 20, \"Concerts\"], [\"Festivals\", \"🎪\", 150, \"Festivals\"], [\"Parties\", \"🎉\", 45, \"Parties\"]];\nfunction setCategory(cat) {\n  category = cat || \"\";\n  document.querySelectorAll(\".chip[data-cat]\").forEach(x => x.classList.toggle(\"selected\", x.dataset.cat === category));\n  renderEvents();\n}\nfunction renderTiles() {\n  $(\"tiles\").innerHTML = VIBES.map(([c, ic, h, label]) => {\n    const n = allEvents.filter(e => e.category === c).length;\n    return `<button class=\"tile\" data-vibe=\"${c}\" style=\"--h:${h}\"><span class=\"emo\">${ic}</span><b>${label}</b><small>${n} ${n === 1 ? \"event\" : \"events\"} live</small></button>`;\n  }).join(\"\");\n}\nfunction renderTicker() {\n  const t = $(\"ticker\"), list = bannerItems();\n  if (!list.length) { t.hidden = true; return; }\n  let seq = list.slice(); while (seq.length < 8) seq = seq.concat(list);\n  const html = seq.map(e => `<span class=\"tk\" data-ev=\"${safe(e.id)}\"><i>✦</i><b>${safe(e.title)}</b><small>${safe(e.city)}</small><em>${Number(e.price) === 0 ? \"Free\" : money(e.price)}</em></span>`).join(\"\");\n  $(\"tickerTrack\").innerHTML = html + html; t.hidden = false;\n}\nfunction countUp(el) {\n  const to = Number(el.dataset.count); if (!to || reduced) { el.textContent = to; return; }\n  const t0 = performance.now();\n  const step = t => { const k = Math.min(1, (t - t0) / 1100); el.textContent = Math.round(to * (1 - Math.pow(1 - k, 3))); if (k < 1) requestAnimationFrame(step); };\n  requestAnimationFrame(step);\n}\nfunction renderStats() {\n  const n = allEvents.length, cities = new Set(allEvents.map(e => String(e.city || \"\").trim().toLowerCase()).filter(Boolean)).size, parts = [];\n  if (n) parts.push(`<div><b data-count=\"${n}\">${n}</b><small>live events</small></div>`);\n  if (cities) parts.push(`<div><b data-count=\"${cities}\">${cities}</b><small>${cities === 1 ? \"city\" : \"cities\"}</small></div>`);\n  parts.push(\"<div><b>QR</b><small>instant tickets</small></div>\");\n  $(\"hxStats\").innerHTML = parts.join(\"\"); $(\"hxStats\").querySelectorAll(\"[data-count]\").forEach(countUp);\n}\nlet io = null;\nif (\"IntersectionObserver\" in window) io = new IntersectionObserver(es => es.forEach(en => {\n  if (!en.isIntersecting) return;\n  en.target.classList.add(\"in\"); en.target.querySelectorAll(\".ring [data-count]\").forEach(countUp); io.unobserve(en.target);\n}), { threshold: 0.12 });\nfunction reveal(nodes, instant) {\n  nodes.forEach(n => { if (n.classList.contains(\"rv\")) return; n.classList.add(\"rv\"); if (!io || instant || reduced) n.classList.add(\"in\"); else io.observe(n); });\n}\n// glowing \"club lights\" floating behind the hero\nfunction startFx() {\n  const cv = $(\"fx\"), hx = $(\"top\"); if (!cv || reduced) return;\n  const ctx = cv.getContext(\"2d\"); if (!ctx) return;\n  let W = 0, H = 0, parts = [], raf = null, visible = true;\n  const size = () => {\n    const dpr = Math.min(2, window.devicePixelRatio || 1); W = cv.clientWidth; H = cv.clientHeight;\n    cv.width = W * dpr; cv.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    parts = Array.from({ length: Math.round(Math.min(58, Math.max(18, W / 24))) }, () => ({ x: Math.random() * W, y: Math.random() * H, r: 2 + Math.random() * 7, vy: 0.12 + Math.random() * 0.4, vx: (Math.random() - 0.5) * 0.18, a: Math.random() * 6.28, s: 0.5 + Math.random() * 1.2, h: Math.random() * 90 - 20 }));\n  };\n  const frame = () => {\n    ctx.clearRect(0, 0, W, H);\n    for (const p of parts) {\n      p.y -= p.vy; p.x += p.vx; p.a += 0.02 * p.s; if (p.y < -30) { p.y = H + 30; p.x = Math.random() * W; }\n      const tw = 0.3 + 0.7 * Math.abs(Math.sin(p.a)), px = p.x + pmx * p.r * 14, py = p.y + pmy * p.r * 14;\n      const g = ctx.createRadialGradient(px, py, 0, px, py, p.r * 3);\n      g.addColorStop(0, `hsla(${fxHue + p.h},95%,72%,${0.6 * tw})`); g.addColorStop(1, `hsla(${fxHue + p.